for t in ('theorem candidate_injective : Function.Injective Sign17KWeightUnion942.indices','congrArg physicalMap h','Finite.surjective_of_injective candidate_injective','physicalPosition (Sign17KWeightUnion942.indices i) = i.val','congrArg Fin.val (Sign17KGlobalAssembly.candidate_positions i)','theorem ranked_tile_sum (r : ℕ)','2 * selectorWeight (tile i) * r ^ (1005 - physicalPosition i)','2 * Sign17KWeightUnion942.weights i * r ^ (1005 - i.val)','candidate_bijective.sum_comp','Sign17KWeightUnion942.all_weights, physical_position'):assert t in s
